const user = $.steps.getCurrentUser.response?.resource || $.steps.getCurrentUser.response || {};
const userUri = user.uri || '';
if (!userUri) throw new Error('Could not determine current user URI');
const params = { user: userUri };
if ($.input.active !== undefined) params.active = String($.input.active);
return { params };

const resp = $.steps.listEventTypes.response || {};
const types = resp.collection || [];
return {
  eventTypes: types.map(t => ({
    uri: t.uri,
    name: t.name,
    slug: t.slug,
    active: t.active,
    duration: t.duration,
    schedulingUrl: t.scheduling_url,
    type: t.type,
    color: t.color,
    description: t.description_plain || t.description_html || ''
  })),
  count: types.length,
  summary: `Found ${types.length} event type${types.length === 1 ? '' : 's'}`
};
